using System;
using System.IO;
using System.Linq;

public static class LapAnalysisTests {
    static void Check(bool condition,string message){if(!condition)throw new Exception("Análise: "+message);}
    static LiveSample Sample(double time,double start,int laps){return new LiveSample{Track="Test track",Car="Car",CarClass="Cup",Driver="Driver",Session=1,Slot=1,SessionTime=time,LapStart=start,Laps=laps,LastLap=82,LastS1=18,LastS12=51,Realtime=true,CountLapFlag=2,Distance=100};}
    public static void Run(){
        var a=new DriverLapPoint{Number=2,Time=82,S1=18,S2=33,S3=31,Complete=true,Valid=true,Pit=false};var b=new DriverLapPoint{Number=7,Time=83,S1=17.5,S2=34,S3=31.5,Complete=true,Valid=true,Pit=false};var invalid=new DriverLapPoint{Number=8,Time=60,S1=10,S2=20,S3=30,Complete=true,Valid=false,Pit=false};
        Check(DriverLapAnalysis.Reference(new[]{a,b,invalid})==a,"A referência deve ser uma volta válida real, não a soma dos melhores setores individuais");Check(DriverLapAnalysis.Value(a,LapMetric.S2)==33&&DriverLapAnalysis.Mean(new[]{a,b,invalid},LapMetric.S1)==17.75,"Analisar cada setor e excluir inválidas da média limpa");
        b.S1=null;Check(!DriverLapAnalysis.Value(b,LapMetric.S1).HasValue&&DriverLapAnalysis.Value(b,LapMetric.S3)==31.5,"Setor ausente não é zero nem deve apagar outro setor disponível");a.S1=0;Check(!DriverLapAnalysis.Value(a,LapMetric.S1).HasValue,"Recusar setor zero");a.S1=double.NaN;Check(!DriverLapAnalysis.Value(a,LapMetric.S1).HasValue,"Recusar NaN");a.S1=19;Check(!DriverLapAnalysis.Value(a,LapMetric.S2).HasValue,"Recusar um conjunto de setores que não corresponde à volta");a.S1=18;
        var old=new TrainingLap{Number=1,Time=82,Valid=true,CompleteData=true};Check(!DriverLapAnalysis.Value(old,LapMetric.S1).HasValue&&DriverLapAnalysis.Value(old,LapMetric.Lap)==82,"Manter históricos antigos sem inventar setores");
        var model=new TrainingModel();model.Arm(new TrainingOptions{Amount=3,Target=82});model.Update(Sample(10,0,0));var line=Sample(80.1,80,1);line.Distance=-.2;model.Update(line);Check(model.Run.State=="running","Distância negativa transitória na meta não deve adiar o início");for(int t=81;t<162;t++)model.Update(Sample(t,80,1));var negative=Sample(161.99,80,1);negative.Distance=-.1;model.Update(negative);Check(model.Run.Active,"Distância negativa transitória não termina o stint");model.Update(Sample(162.1,162,2));Check(model.Run.Laps.Count==1&&model.Run.Laps[0].S1==18&&model.Run.Laps[0].S2==33&&model.Run.Laps[0].S3==31,"Guardar setores emparelhados da volta completa");
        for(int t=163;t<244;t++)model.Update(Sample(t,162,2));var transient=Sample(244.1,244,3);transient.Realtime=false;model.Update(transient);Check(model.Run.Active&&model.Run.Laps.Count==1,"Uma amostra fora de realtime na meta pausa, sem concluir o objetivo");model.Update(Sample(244.3,244,3));Check(model.Run.Active&&model.Run.Laps.Count==2,"Retomar e recuperar a passagem de meta após a amostra transitória");for(int t=245;t<326;t++)model.Update(Sample(t,244,3));model.Update(Sample(326.1,326,4));Check(model.Run.State=="completed"&&model.Run.Laps.Count==3,"Só concluir depois das voltas previstas");
        var incomplete=new TrainingLap{Time=82,CompleteData=false};DriverLapAnalysis.CaptureSectors(incomplete,Sample(326.1,326,4),true);Check(!incomplete.S1.HasValue,"Uma volta incompleta não herda contadores de setores anteriores");
        var paused=new TrainingModel();paused.Arm(new TrainingOptions{Minutes=true,Amount=1});paused.Update(Sample(10,0,0));paused.Update(Sample(80.1,80,1));for(int t=81;t<162;t++)paused.Update(Sample(t,80,1));var menu=Sample(162.1,162,2);menu.Realtime=false;paused.Update(menu);menu=Sample(167.1,162,2);menu.Realtime=false;paused.Update(menu);paused.Update(Sample(167.2,162,2));Check(paused.Run.State=="completed"&&Math.Abs(paused.Run.Elapsed-82)<.00001,"Uma pausa depois da meta não pode subtrair tempo à volta que já terminou");
        TrainingStore.Save(model.Run);var stored=TrainingStore.History().First(r=>r.Id==model.Run.Id);Check(stored.Laps[0].S1==18&&stored.Laps[0].S3==31,"Persistência dos setores no treino");
        Check(AnalysisLegend.Point(true,82,82)==AnalysisLegend.Green&&AnalysisLegend.Point(true,83,82)==AnalysisLegend.Red&&AnalysisLegend.Point(false,80,82)==GtcTheme.Muted,"Cores da legenda distinguem referência e validade");
        Check(AnalysisLegend.Point(true,83.2,82.7,.5)==AnalysisLegend.Green&&AnalysisLegend.Point(true,82.2,82.7,.5)==AnalysisLegend.Green&&AnalysisLegend.Point(true,82.19,82.7,.5)==AnalysisLegend.FastGreen&&AnalysisLegend.Point(true,83.21,82.7,.5)==AnalysisLegend.Red,"A janela inclui os limites e voltas mais rápidas, assinaladas em verde carregado");
        File.WriteAllText(Path.Combine(CompanionStore.Root,"lap-analysis-tests.txt"),"OK: setores independentes; referência de uma volta real; setores ausentes/zero/inconsistentes; média limpa; históricos antigos; distância negativa e realtime transitórios na meta; recuperação da contagem; conclusão só no objetivo; captura e persistência dos setores; cores da legenda.");
    }
}
